/**
 * The adversary, pointed at the two published circuit families it was built for.
 *
 * **This is a known-answer test, not a discovery.** Both families were classically
 * reproduced by other groups after publication — the 127-qubit Trotter circuits
 * within months, by tensor-network and Pauli-propagation methods, and Sycamore-class
 * random circuit sampling by large-scale contraction. A break here says the
 * adversary agrees with results that already exist. That is worth knowing precisely
 * because every earlier measurement in this project used circuits generated by the
 * same code that then attacked them.
 *
 * What is reproduced here is the published *circuit structure*: IBM's heavy-hex
 * coupling map with Rzz(−π/2) + Rx(θ) Trotter steps, and Google's coupler-pattern
 * sequence with fSim(π/2, π/6) and the √X/√Y/√W single-qubit set. Not calibration
 * data, not a specific chip's dead qubits. Hardness is a property of the graph, so
 * relabelling does not matter; the boundary shape does, slightly, and the Sycamore
 * instance here is a 54-site rectangle rather than the exact chip outline.
 *
 * Run with: node --max-old-space-size=16384 benchmark/published-circuits.ts
 *
 * 16 GB and not 8: the attacks here are priced against `BUDGET.memoryBytes`, and
 * a heap smaller than the budget means a verdict of "nothing landed within 16 GB"
 * that was never given 16 GB to work with.
 */
import {
  ATTACK_NAMES, DEVICES, heavyHex127, gridCouplings, rcsCircuit, renderSearch,
  searchHardness, trotterIsing, type Circuit,
} from '@kirkelliott/ket'

/**
 * Probes decide the search; `attemptTerms` decides the verdict.
 *
 * A probe caps the work and reports whatever it reached, so a capped attack comes
 * back marked `≥` — a floor, not a measurement. That is the right trade while the
 * rewrite search is pricing hundreds of candidates, and the wrong one for the
 * final answer: with no attempt budget every target here reported
 * `Pauli terms = 4096` whatever its depth, which is `probeTerms` restated rather
 * than anything about the circuit. `searchHardness` withholds `attemptTerms`
 * during the search and applies it once to the winner, so an attempt costs one
 * pair of runs, not one per candidate.
 *
 * The size is derived, because picking it by feel reintroduces the same bug one
 * order of magnitude up: an attempt that stops early also reports a floor, and a
 * floor printed beside "nothing landed" still reads as a claim about the circuit
 * when it is a claim about this constant.
 *
 * Two ceilings apply and the lower one wins.
 *
 * The budget's own: `hardness.ts` charges `qubits * 2 + 64` bytes per retained
 * term and `gates * terms` operations, so at the widest target — 127 qubits, ~9k
 * gates after the light cone — memory binds before time, admitting ~5.0e7 terms
 * where 3600 s at 2e8 ops/s would allow ~8.0e7. Halved for the propagation's
 * working set, that is ~2.5e7.
 *
 * And a tractability ceiling: 100x the probe. `opsPerSecond` is calibrated for
 * tensor contraction, and Pauli propagation does not obey it — its cost is
 * dominated by hashing and merging Pauli strings rather than arithmetic, and a
 * 2.5e7-term attempt measured at over ten minutes on a *single* target against a
 * predicted two. A benchmark nobody will wait for does not get run.
 *
 * 100x the cap is where those meet: it resolves two orders of magnitude more than
 * the probe could, and the deepest targets may still come back as floors. That is
 * a real measurement — "asked with 400k terms and it still moved" — rather than
 * the old `= 4096`, which only ever restated `probeTerms`.
 */
const PROBE_TERMS = 4096
const ATTEMPT_TERMS = Math.min(100 * PROBE_TERMS, 25_000_000)

const BUDGET = {
  memoryBytes: 16e9, seconds: 3600, probeChi: 4, probeTerms: PROBE_TERMS, restarts: 8,
  attemptTerms: ATTEMPT_TERMS,
  // The output here is a verdict per circuit, not a cost table to read row by
  // row, so resolving an attack that has already lost is spend for nothing. The
  // shallow targets are broken by a 16 MB contraction; without this they still
  // paid to price a Pauli attack that could not have displaced it.
  attemptOnlyIfDecisive: true,
  // Calibration is the case the default gate exists to protect everything *else*
  // from. A width is only worth quoting at its tightest, and bisection reaches 55
  // where greedy reaches 78 on the ten-step network, so the minutes of planning
  // are the point rather than the cost. Interactive callers keep the default.
  probeMaxGates: Infinity,
}
const say = (s: string): void => { process.stdout.write(`${s}\n`) }
const rule = (s: string): void => say(`\n${'═'.repeat(76)}\n${s}`)

/** One target: what it is, the circuit, and the qubit the question is about. */
interface Target { label: string; circuit: Circuit; about: number[]; noise?: { p1: number; p2: number } }

/** Single-site Z, in the one-letter-per-qubit convention the Pauli backends take. */
const zAt = (n: number, q: number) =>
  [{ coeff: 1, ops: Array.from({ length: n }, (_, k) => k === n - 1 - q ? 'Z' : 'I').join('') }]

function ibm(depth: number, thetaH: number): Target {
  return {
    label: `IBM utility — heavy-hex 127q, ${depth} Trotter steps, Rx(θ=${thetaH.toFixed(3)})`,
    circuit: trotterIsing({ qubits: 127, coupling: heavyHex127(), depth, thetaH }),
    about: [62],   // a mid-lattice qubit, as the published single-site observables were
    noise: { p1: DEVICES['ibm_sherbrooke']!.noise.p1!, p2: DEVICES['ibm_sherbrooke']!.noise.p2! },
  }
}

function google(depth: number): Target {
  // 6x9 = 54 sites, Sycamore's qubit count. gridCouplings gives the same four
  // disjoint coupler patterns the published sequence cycles through.
  return {
    label: `Google RCS — 54q lattice, depth ${depth}, fSim(π/2, π/6)`,
    circuit: rcsCircuit({ rows: 6, cols: 9, depth, seed: 1 }),
    about: [27],
  }
}

const targets: Target[] = [
  ibm(5, Math.PI / 4),
  ibm(10, Math.PI / 4),
  ibm(20, Math.PI / 4),
  google(12),
  google(20),
]

say('KNOWN-ANSWER TEST — both families were classically reproduced by others.')
say('A break here validates the adversary; it does not discover anything.\n')
say(`budget: ${BUDGET.memoryBytes / 1e9} GB / ${BUDGET.seconds / 3600} h, probeChi ${BUDGET.probeChi}`)

for (const { label, circuit, about, noise } of targets) {
  rule(label)
  const gates = circuit.gateCounts().total
  say(`${circuit.qubits} qubits, ${gates} gates — asked about ⟨Z${about[0]}⟩`)
  const t0 = performance.now()
  // The observable matters: without it both Pauli-path attacks decline, and
  // sparse Pauli propagation is the method that reproduced these circuits in the
  // literature. Omitting it disables the attack most likely to land.
  const s = searchHardness(circuit, {
    ...BUDGET, about,
    observable: zAt(circuit.qubits, about[0]!),
    ...(noise !== undefined && { noise }),
  })
  say(renderSearch(s))
  // Driven off the exported roster rather than a hand-written list, so an attack
  // added to the library cannot be silently missing from its own calibration.
  for (const name of ATTACK_NAMES) {
    if (name === 'statevector') continue          // the baseline, printed as `advantage`
    const a = s.after.attacks.find(x => x.name === name)!
    // Carry the bound, as renderHardness does. A capped probe and a converged
    // attempt print the same number otherwise, and the difference between them is
    // the difference between "this circuit is hard" and "nobody asked".
    const mark = a.parameter === undefined || a.parameter.bound === 'exact' ? '' : a.parameter.bound === 'lower' ? '≥' : '≤'
    say(`  ${(a.viable ? '✓' : '·') + ' ' + name.padEnd(17)}` +
      (a.parameter ? `${a.parameter.name} = ${mark}${a.parameter.value}` : (a.reason ?? '').slice(0, 60)))
  }
  say(`(${((performance.now() - t0) / 1000).toFixed(0)}s)`)
}
